#include "../src/effects/halloween/scene.h"
#include "../src/effects/halloween/sprite_geometry.h"
#include "../src/occlusion.h"
#include <cstdio>
#include <functional>
#include <stdexcept>
using namespace halloweenfx;
static Settings config;Settings& halloweenfx::Cfg(){return config;}
static void Check(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
static void Reset(){config=Settings();config.intensity=0;config.angle=0;config.gusts=0;config.cursorWind=0;config.flutter=0;config.tumble=0;RngState()=1234567;}
static World Desktop(int width=1920,int height=1080,float scale=1){World w;w.virt={0,0,width,height};MonitorInfo m;m.rc=w.virt;m.work={0,0,width,height-(int)(40*scale)};m.groundY=m.work.b;m.scale=scale;w.monitors.push_back(m);return w;}
static void Window(World& w,uintptr_t key,RectI rect){w.wins.push_back({(HWND)key,rect,false,false});}
static Surface& Find(Scene& s,uintptr_t key){for(auto& p:s.surfaces)if(p.key==key)return p;throw std::runtime_error("surface missing");}
static void Step(Scene& s,World& w,int n,float dt=1.0f/60){for(int i=0;i<n;++i)s.Update(dt,w,{0,0},false);}
static Particle Falling(float x,float y,int family=FAMILY_CANDY,int variant=0){Particle p;p.x=x;p.y=y;p.vy=900;p.size=16;p.family=family;p.variant=variant;p.z=1;p.life=60;p.spin=1;return p;}
static void Deposit(Scene& s,World& w,uintptr_t key,int n,int family=FAMILY_CANDY,float x=120){for(int i=0;i<n;++i){auto& edge=Find(s,key);int c=std::clamp((int)(x/kCell),0,edge.cells-1);int variant=i%(family==FAMILY_CANDY?6:4);auto p=Falling(edge.left+x,0,family,variant);p.y=edge.top-edge.h[c]-ParticleOpaqueBounds(family,variant,0).bottom*16-4;s.airborne.push_back(p);Step(s,w,1,1.0f/30);}}
static WebSpider Hanging(float x=500,float y=200,float scale=1){WebSpider s;s.id=11;s.anchorX=x;s.anchorY=0;s.x=x;s.y=y;s.targetY=y;s.scale=scale;s.size=16*scale;s.monitor={0,0,1920,1080};s.state=SPIDER_HANGING;s.wait=20;s.variant=2;return s;}
static void Finite(const Scene& s){Check(s.airborne.size()<=kMaxAirborne&&s.SettledCount()<=kMaxSettled&&s.webs.size()<=kMaxWebSpiders,"population budget exceeded");for(auto& edge:s.surfaces){for(float h:edge.h)Check(std::isfinite(h)&&h>=0&&h<=edge.maxH+.001f,"invalid pile height");for(auto p:edge.objects)Check(p.family<2&&p.variant<kSpriteVariants[p.family]&&p.base>=0,"invalid settled sprite");}for(auto p:s.airborne)Check(p.family<2&&p.variant<kSpriteVariants[p.family]&&std::isfinite(p.x)&&std::isfinite(p.y),"invalid flying sprite");for(auto p:s.webs)Check(p.variant<4&&std::isfinite(p.x)&&std::isfinite(p.y)&&p.speed>0,"invalid tethered spider");}
int main(){int passed=0,failed=0;auto test=[&](const char* name,std::function<void()> fn){Reset();try{fn();++passed;std::printf("PASS %s\n",name);}catch(const std::exception& e){++failed;std::printf("FAIL %s: %s\n",name,e.what());}};
 test("16px default and six/four variant bounds",[]{Check(NativeParticleSize(0)==8&&NativeParticleSize(50)==16&&NativeParticleSize(100)==32,"size mapping wrong");Check(VariantCount(100,0)==6&&VariantCount(100,1)==4&&VariantCount(0,0)==1,"variant mapping wrong");});
 test("all six candies are emitted",[]{Cfg().intensity=100;Cfg().contentMode=CONTENT_CANDY;auto w=Desktop();Scene s;s.Sync(w);Step(s,w,1);bool seen[6]={};for(auto p:s.airborne){Check(p.family==0,"wrong family");seen[p.variant]=true;}for(bool v:seen)Check(v,"candy variant missing");});
 test("candy-only mode never creates web spiders",[]{Cfg().intensity=60;Cfg().contentMode=CONTENT_CANDY;auto w=Desktop();Scene s;s.Sync(w);Step(s,w,600);Check(s.webs.empty()&&!s.SpawnWebSpider(w)&&!s.airborne.empty(),"candy-only mode wrong");});
 test("spider-only mode never emits candy",[]{Cfg().intensity=60;Cfg().contentMode=CONTENT_SPIDERS;auto w=Desktop();Scene s;s.Sync(w);Step(s,w,300);Check(!s.webs.empty(),"no spiders");for(auto p:s.airborne)Check(p.family==1,"candy emitted in spider mode");});
 test("both mode creates candy and tethered spiders",[]{Cfg().intensity=60;auto w=Desktop();Scene s;s.Sync(w);Step(s,w,1);Check(!s.airborne.empty()&&!s.webs.empty(),"both mode incomplete");});
 test("mode changes remove excluded families from all states",[]{auto w=Desktop();Scene s;s.Sync(w);auto ground=s.surfaces[0].key;Deposit(s,w,ground,2,0);Deposit(s,w,ground,2,1,250);s.webs.push_back(Hanging());s.airborne.push_back(Falling(500,50,1));Cfg().contentMode=CONTENT_CANDY;s.Sync(w);Check(s.webs.empty(),"thread survived mode switch");for(auto p:s.airborne)Check(p.family==0,"spider survived in air");for(auto& edge:s.surfaces)for(auto p:edge.objects)Check(p.family==0,"spider survived in pile");});
 test("falling candy obeys wind and rotation",[]{Cfg().angle=25;Cfg().tumble=100;auto w=Desktop();Scene s;auto p=Falling(500,100);p.vy=100;s.airborne.push_back(p);Step(s,w,120);Check(s.airborne[0].x>520&&s.airborne[0].y>200&&s.airborne[0].rotation>1,"flight controls ignored");});
 test("both sprite families land on windows and taskbar",[]{auto w=Desktop();Window(w,1,{100,300,900,750});Scene s;s.Sync(w);Deposit(s,w,1,4,0);Deposit(s,w,s.surfaces[0].key,4,1,1000);Check(Find(s,1).objects.size()==4&&!s.surfaces[0].objects.empty(),"mixed piles missing");Finite(s);});
 test("full-face sprites overlap compact dense collision layers",[]{auto w=Desktop();Window(w,1,{100,300,900,750});Scene s;s.Sync(w);Deposit(s,w,1,5);Check(kRestingSpriteSquash==1&&kRestingCollisionHalfWidth<.3f,"flattened or oversized collision");Check(Find(s,1).objects.size()==5&&Find(s,1).objects.back().base<8,"pile has excessive gaps");for(auto p:Find(s,1).objects)Check(RestingParticleVisibleTop(p,p.family)>p.base+4,"full face clipped");});
 test("15 FPS swept collision chooses nearest edge",[]{auto w=Desktop();Window(w,1,{100,300,900,500});Window(w,2,{100,500,900,850});Scene s;s.Sync(w);auto p=Falling(400,240);p.vy=1800;s.airborne.push_back(p);Step(s,w,1,1.0f/15);Check(Find(s,1).objects.size()==1&&Find(s,2).objects.empty(),"wrong landing edge");});
 test("window drag, shake and resize keep pile ownership",[]{auto w=Desktop();Window(w,1,{100,300,900,750});Scene s;s.Sync(w);Deposit(s,w,1,10,0,650);Step(s,w,60);auto n=Find(s,1).objects.size();w.wins[0].rc={150,300,950,750};s.Sync(w);Check(Find(s,1).objects.size()==n,"slow drag lost objects");s.Sync(w);w.wins[0].rc={500,300,1300,750};s.Sync(w);Check(Find(s,1).objects.size()<n,"shake did not release objects");w.wins[0].rc={500,300,800,750};s.Sync(w);Check(Find(s,1).objects.empty(),"resize kept objects beyond edge");});
 test("cursor, shake and clear release and remove objects",[]{auto w=Desktop();Window(w,1,{100,300,900,750});Scene s;s.Sync(w);Deposit(s,w,1,5);auto n=s.SettledCount();s.Update(1.0f/60,w,{227,290},true);Check(s.SettledCount()<n&&!s.airborne.empty(),"cursor failed");Deposit(s,w,1,3,1,250);s.ShakeAll();Check(s.SettledCount()==0,"shake failed");s.webs.push_back(Hanging());s.ClearAll();Check(s.Idle()&&s.webs.empty()&&s.airborne.empty(),"clear left actors");});
 test("decay removes old collected objects",[]{Cfg().decay=100;auto w=Desktop();Scene s;s.Sync(w);Deposit(s,w,s.surfaces[0].key,4);Step(s,w,1200);Check(s.SettledCount()==0,"pile did not decay");});
 test("mixed DPI and maximum motion stay finite",[]{Cfg().intensity=100;Cfg().fallSpeed=100;Cfg().angle=60;Cfg().gusts=100;Cfg().flutter=100;Cfg().tumble=100;Cfg().spiderInterval=4;auto w=Desktop(5760,2160);w.monitors[0].rc={0,0,1920,1080};w.monitors[0].groundY=1040;MonitorInfo m;m.rc={1920,0,5760,2160};m.work={1920,0,5760,2080};m.groundY=2080;m.scale=2;w.monitors.push_back(m);Window(w,1,{200,300,1700,900});Scene s;s.Sync(w);for(int i=0;i<1800;++i){s.Update(i%2?1.0f/15:1.0f/144,w,{i%5700,700},true);if(i%50==0)s.Sync(w);if(i%100==0)Finite(s);}Finite(s);});
 test("zero density and frame bounds remain predictable",[]{auto w=Desktop();Scene s;s.Sync(w);Step(s,w,120);Check(s.Idle(),"zero density spawned actors");auto p=Falling(500,100);p.vy=100;s.airborne.push_back(p);s.Update(0,w,{0,0},false);Check(s.airborne[0].y==100,"zero frame moved actor");s.Update(10,w,{0,0},false);Check(s.airborne[0].y<120,"large frame was not clamped");});
 test("spider starts attached to its monitor ceiling",[]{auto w=Desktop();Scene s;s.Sync(w);Check(s.SpawnWebSpider(w),"spawn failed");auto p=s.webs[0];Check(p.state==SPIDER_DESCENDING&&p.y<p.targetY&&p.anchorY==0&&p.variant<4,"initial spider invalid");});
 test("partial descent setting stops before the bottom",[]{Cfg().partialDescents=100;auto w=Desktop();Scene s;s.Sync(w);for(int i=0;i<100;++i){s.webs.clear();Check(s.SpawnWebSpider(w),"spawn failed");auto p=s.webs[0];Check(p.partial&&p.targetY<800,"partial descent went all the way");}});
 test("full descent setting approaches the floor",[]{Cfg().partialDescents=0;auto w=Desktop();Scene s;s.Sync(w);Check(s.SpawnWebSpider(w),"spawn failed");auto p=s.webs[0];Check(!p.partial&&p.targetY>1000&&p.targetY<1040,"full descent target wrong");});
 test("descending spider moves slowly and keeps its thread",[]{auto w=Desktop();Scene s;s.Sync(w);s.SpawnWebSpider(w);float y=s.webs[0].y;Step(s,w,60);Check(s.webs[0].y>y+10&&s.webs[0].y<y+40,"spider descent too fast or stopped");auto t=Scene::Thread(s.webs[0]);Check(t.by>t.ay&&t.ay==0,"thread missing");});
 test("reaching target changes descent into hanging",[]{auto w=Desktop();Scene s;s.Sync(w);auto p=Hanging();p.state=SPIDER_DESCENDING;p.targetY=p.y+1;s.webs.push_back(p);Step(s,w,10);Check(s.webs[0].state==SPIDER_HANGING&&s.webs[0].y==p.targetY,"spider did not pause at target");});
 test("hanging pause is respected before any choice",[]{auto w=Desktop();Scene s;s.Sync(w);auto p=Hanging();p.wait=2;s.webs.push_back(p);Step(s,w,60);Check(s.webs.size()==1&&s.webs[0].state==SPIDER_HANGING&&s.airborne.empty(),"choice happened too early");});
 test("real lifecycle decisions split approximately 50/50",[]{auto w=Desktop();Scene s;s.Sync(w);int climb=0,drop=0;for(int i=0;i<1000;++i){s.webs.clear();s.airborne.clear();auto p=Hanging();p.wait=0;s.webs.push_back(p);Step(s,w,1);if(!s.webs.empty()&&s.webs[0].state==SPIDER_ASCENDING)++climb;else if(s.webs.empty()&&s.airborne.size()==1)++drop;else Check(false,"invalid decision transition");}Check(climb>430&&climb<570&&drop==1000-climb,"decision split outside tolerance");});
 test("ascending spider exits above the ceiling",[]{auto w=Desktop();Scene s;s.Sync(w);auto p=Hanging(500,10);p.state=SPIDER_ASCENDING;s.webs.push_back(p);Step(s,w,180);Check(s.webs.empty()&&s.airborne.empty(),"climbed spider failed to leave");});
 test("voluntary release preserves spider family and variant",[]{auto w=Desktop();Scene s;s.Sync(w);bool seen=false;for(int i=0;i<30&&!seen;++i){s.webs.clear();s.airborne.clear();auto p=Hanging();p.wait=0;p.variant=3;s.webs.push_back(p);Step(s,w,1);if(!s.airborne.empty()){Check(s.airborne[0].family==FAMILY_SPIDER&&s.airborne[0].variant==3,"release lost identity");seen=true;}}Check(seen,"no release observed");});
 test("clicking a thread instantly releases its spider",[]{auto w=Desktop();Scene s;s.Sync(w);s.webs.push_back(Hanging());Check(s.CutWebAt({500,100},w),"thread was not cut");Check(s.webs.empty()&&s.airborne.size()==1&&s.airborne[0].family==1,"cut did not release spider");});
 test("a missed thread click leaves the scene untouched",[]{auto w=Desktop();Scene s;s.Sync(w);s.webs.push_back(Hanging());Check(!s.CutWebAt({550,100},w)&&s.webs.size()==1&&s.airborne.empty(),"miss changed the scene");});
 test("thread hit tolerance follows monitor scale",[]{auto w=Desktop();Scene s;s.Sync(w);s.webs.push_back(Hanging(500,200,2));Check(!s.CutWebAt({509,100},w),"outside tolerance cut thread");Check(s.CutWebAt({507,100},w),"scaled tolerance failed");});
 test("cut-thread switch disables interaction",[]{Cfg().cutWebs=false;auto w=Desktop();Scene s;s.Sync(w);s.webs.push_back(Hanging());Check(!s.CutWebAt({500,100},w)&&s.webs.size()==1,"disabled cutting still works");});
 test("hidden or disabled effects cannot receive thread clicks",[]{auto w=Desktop();Scene s;s.Sync(w);s.webs.push_back(Hanging());Cfg().webOpacity=0;Check(!s.CutWebAt({500,100},w),"invisible thread cut");Cfg().webOpacity=80;Cfg().showFalling=false;Check(!s.CutWebAt({500,100},w),"hidden animation cut");Cfg().showFalling=true;Cfg().objectOpacity=0;Check(!s.CutWebAt({500,100},w),"invisible spider cut");Cfg().objectOpacity=100;Cfg().enabled=false;Check(!s.CutWebAt({500,100},w),"disabled scene cut");});
 test("behind-window mode clips thread drawing and hit testing",[]{Cfg().mode=MODE_BEHIND;auto w=Desktop();Window(w,1,{450,50,550,150});Scene s;s.Sync(w);s.webs.push_back(Hanging());Check(!s.CutWebAt({500,100},w),"cut through foreground window");Check(s.CutWebAt({500,30},w),"visible thread could not be cut");});
 test("one click cuts only the closest overlapping thread",[]{auto w=Desktop();Scene s;s.Sync(w);auto a=Hanging(500),b=Hanging(502);a.id=1;b.id=2;s.webs={a,b};Check(s.CutWebAt({500,100},w),"cut failed");Check(s.webs.size()==1&&s.webs[0].id==2&&s.airborne.size()==1,"one click cut wrong number");});
 test("ascending thread can be cut without changing its pose",[]{auto w=Desktop();Scene s;s.Sync(w);auto p=Hanging();p.state=SPIDER_ASCENDING;p.variant=1;s.webs.push_back(p);Check(s.CutWebAt({500,100},w),"ascending thread not cut");Check(s.airborne[0].variant==1&&s.airborne[0].rotation>3,"cut changed ascending pose");});
 test("tethered spider budget is enforced",[]{auto w=Desktop();Scene s;s.Sync(w);for(int i=0;i<40;++i)s.SpawnWebSpider(w);Check(s.webs.size()==kMaxWebSpiders&&!s.SpawnWebSpider(w),"web population limit ignored");});
 test("fullscreen pause and monitor removal protect interaction",[]{auto w=Desktop();Scene s;s.Sync(w);s.webs.push_back(Hanging());w.gameOrFullscreen=true;Check(!s.CutWebAt({500,100},w),"paused fullscreen received a cut");w.gameOrFullscreen=false;w.monitors.clear();Step(s,w,1);Check(s.webs.empty(),"removed monitor kept orphan thread");});
 std::printf("\n%d passed, %d failed\n",passed,failed);return failed?1:0;
}
